<?php

use Illuminate\Contracts\Http\Kernel;
use Illuminate\Http\Request;

header('Content-Type: text/plain; charset=utf-8');
if (($_GET['key'] ?? '') !== 'tpi-fix-2026') {
    http_response_code(403);
    echo "Forbidden\n";
    exit;
}

$root = dirname(__DIR__);
$cache = $root.'/bootstrap/cache';
if (! is_dir($cache)) {
    mkdir($cache, 0775, true);
}

$packages = base64_decode('');
$services = base64_decode('');
file_put_contents($cache.'/packages.php', $packages);
file_put_contents($cache.'/services.php', $services);
echo "OK: wrote PRODUCTION packages.php / services.php\n";

// Show real boot error
error_reporting(E_ALL);
ini_set('display_errors', '1');
try {
    require $root.'/vendor/autoload.php';
    echo "OK: autoload\n";
    $app = require $root.'/bootstrap/app.php';
    echo "OK: bootstrap/app.php\n";
    $kernel = $app->make(Kernel::class);
    echo "OK: http kernel\n";
    $request = Request::create('/api/login', 'POST', [], [], [], [
        'HTTP_ACCEPT' => 'application/json',
        'CONTENT_TYPE' => 'application/json',
    ], json_encode([
        'email' => 'sales@tpi.com',
        'password' => '12345678',
        'device_name' => 'diag',
    ]));
    $response = $kernel->handle($request);
    echo 'LOGIN HTTP '.$response->getStatusCode()."\n";
    echo $response->getContent()."\n";
} catch (Throwable $e) {
    echo "BOOT/LOGIN ERROR\n";
    echo get_class($e).': '.$e->getMessage()."\n";
    echo $e->getFile().':'.$e->getLine()."\n";
    echo $e->getTraceAsString()."\n";
}
